[
    {
        "id": "HP1",
        "sort": 100,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Plahvatusohtlik",
            "en": "Explosive"
        },
        "description": {
            "et": "Plahvatusohtlik: jäätmed, mis võivad keemilise reaktsiooni teel tekitada gaasi sellise temperatuuri, rõhu ja kiirusega, mis kahjustab ümbruskonda; sealhulgas pürotehnilised jäätmed, plahvatusohtlikud orgaanilise peroksiidi jäätmed ja plahvatusohtlikud isereageerivad jäätmed",
            "en": "“Explosive:” waste which is capable by chemical reaction of producing gas at such a temperature and pressure and at such a speed as to cause damage to the surroundings. Pyrotechnic waste, explosive organic peroxide waste and explosive self-reactive waste is included"
        }
    },
    {
        "id": "HP2",
        "sort": 200,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Oksüdeeriv",
            "en": "Oxidising"
        },
        "description": {
            "et": "Oksüdeeriv: jäätmed, mis võivad tavaliselt hapniku loovutamise kaudu põhjustada teise materjali põlemist või sellele kaasa aidata",
            "en": "“Oxidising:” waste which may, generally by providing oxygen, cause or contribute to the combustion of other materials"
        }
    },
    {
        "id": "HP3",
        "sort": 300,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Tuleohtlik",
            "en": "Flammable"
        },
        "description": {
            "et": "Tuleohtlik: tuleohtlikud vedeljäätmed, mille leektäpp on alla 60 °C, või jäätmegaasiõli, diislikütus ja kerged kütteõlid, mille leektäpp on > 55 °C ja ≤ 75 °C; tuleohtlikud pürofoorsed vedel- ja tahked jäätmed: tahked või vedeljäätmed, mis võivad isegi väikeses koguses süttida viie minuti jooksul pärast kokkupuudet õhuga; tuleohtlikud tahked jäätmed: tahked jäätmed, mis on kergesti süttivad või võivad põhjustada süttimist või süttimisele kaasa aidata hõõrdumise tulemusena;  tuleohtlikud gaasilised jäätmed: gaasilised jäätmed, mis on tuleohtlikud õhutemperatuuril 20 °C ja normaalrõhul 101,3 kPa; veega reageerivad jäätmed: jäätmed, mis kokkupuutel veega eraldavad ohtlikus koguses tuleohtlikke gaase; muud tuleohtlikud jäätmed: tuleohtlikud aerosoolid, tuleohtlikud isekuumenevad jäätmed, tuleohtlikud orgaanilised peroksiidid ja tuleohtlikud isereageerivad jäätmed",
            "en": "“Flammable:” flammable liquid waste: liquid waste having a flash point below 60 °C or waste gas oil, diesel and light heating oils having a flash point > 55 °C and ≤ 75 °C; flammable pyrophoric liquid and solid waste: solid or liquid waste which, even in small quantities, is liable to ignite within five minutes after coming into contact with air; flammable solid waste: solid waste which is readily combustible or may cause or contribute to fire through friction; flammable gaseous waste: gaseous waste which is flammable in air at 20 °C and a standard pressure of 101.3 kPa; water reactive waste: waste which, in contact with water, emits flammable gases in dangerous quantities; other flammable waste: flammable aerosols, flammable self-heating waste, flammable organic peroxides and flammable self-reactive waste"
        }
    },
    {
        "id": "HP4",
        "sort": 400,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Ärritav",
            "en": "Irritant"
        },
        "description": {
            "et": "Ärritav - nahka ärritav ja silmi kahjustav: jäätmed, mis kokkupuutel võivad põhjustada nahaärritust või kahjustada silma",
            "en": "“Irritant - skin irritation and eye damage:” waste which on application can cause skin irritation or damage to the eye"
        }
    },
    {
        "id": "HP5",
        "sort": 500,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Mürgisus",
            "en": "Specific"
        },
        "description": {
            "et": "Mürgisus sihtelundi suhtes/hingamiskahjustusi tekitav mürgisus: jäätmed, mis võivad põhjustada mürgisust sihtelundi suhtes kas ühekordsel või korduval kokkupuutel, või mis põhjustavad ägedat toksilist mõju sissehingamisel",
            "en": "“Specific Target Organ Toxicity (STOT)/Aspiration Toxicity:” waste which can cause specific target organ toxicity either from a single or repeated exposure, or which cause acute toxic effects following aspiration"
        }
    },
    {
        "id": "HP6",
        "sort": 600,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Äge mürgisus",
            "en": "Acute"
        },
        "description": {
            "et": "Äge mürgisus: jäätmed, mis võivad põhjustada ägedat toksilist mõju suukaudsel või nahakaudsel manustamisel või sissehingamisel",
            "en": "“Acute Toxicity:” waste which can cause acute toxic effects following oral or dermal administration, or inhalation exposure"
        }
    },
    {
        "id": "HP7",
        "sort": 700,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Kantserogeenne",
            "en": "Carcinogenic"
        },
        "description": {
            "et": "Kantserogeenne: jäätmed, mis tekitavad vähktõbe või suurendavad selle esinemissagedust",
            "en": "“Carcinogenic:” waste which induces cancer or increases its incidence"
        }
    },
    {
        "id": "HP8",
        "sort": 800,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Söövitav",
            "en": "Corrosive"
        },
        "description": {
            "et": "Söövitav: jäätmed, mis võivad kokkupuutel põhjustada naha söövituse",
            "en": "“Corrosive:” waste which on application can cause skin corrosion"
        }
    },
    {
        "id": "HP9",
        "sort": 900,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Nakkust tekitav",
            "en": "Infectious"
        },
        "description": {
            "et": "Nakkust tekitav: jäätmed, mis sisaldavad mikroorganisme või nende toksiine, mida teatakse kindlasti või tõenäoliselt põhjustavat inimeste või muude elusorganismide haigestumist",
            "en": "“Infectious:” waste containing viable micro-organisms or their toxins which are known or reliably believed to cause disease in man or other living organisms"
        }
    },
    {
        "id": "HP10",
        "sort": 1000,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Reproduktiivtoksiline",
            "en": "Toxic"
        },
        "description": {
            "et": "Reproduktiivtoksiline: jäätmed, millel on kahjulik toime täiskasvanud meeste ja naiste ning isas- ja emasloomade suguvõimele ja viljakusele, samuti järglaste arengut mõjutav mürgisus (arengutoksilisus)",
            "en": "“Toxic for reproduction:” waste which has adverse effects on sexual function and fertility in adult males and females, as well as developmental toxicity in the offspring"
        }
    },
    {
        "id": "HP11",
        "sort": 1100,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Mutageenne",
            "en": "Mutagenic"
        },
        "description": {
            "et": "Mutageenne: jäätmed, mis võivad põhjustada mutatsiooni - püsivat muutust raku geneetilise materjali koguses või struktuuris",
            "en": "“Mutagenic:” waste which may cause a mutation, that is a permanent change in the amount or structure of the genetic material in a cell"
        }
    },
    {
        "id": "HP12",
        "sort": 1200,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Eraldab väga mürgiseid gaase",
            "en": "Release"
        },
        "description": {
            "et": "Eraldab väga mürgiseid gaase: jäätmed, mille kokkupuutel vee, õhu või happega tekivad väga mürgised gaasid (Äge mürgisus 1, 2 või 3)",
            "en": "“Release of an acute toxic gas:” waste which releases acute toxic gases (Acute Tox. 1, 2 or 3) in contact with water or an acid"
        }
    },
    {
        "id": "HP13",
        "sort": 1300,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Sensibiliseeriv",
            "en": "Sensitising"
        },
        "description": {
            "et": "Sensibiliseeriv: jäätmed, mis sisaldavad üht või mitut ainet, millel on teadaolevalt ülitundlikkust tekitav toime nahale või hingamisteedele",
            "en": "“Sensitising:” waste which contains one or more substances known to cause sensitising effects to the skin or the respiratory organs"
        }
    },
    {
        "id": "HP14",
        "sort": 1400,
        "valid_from": "2016-01-01",
        "valid_to": null,
        "name": {
            "et": "Keskkonnaohtlik",
            "en": "Ecotoxic"
        },
        "description": {
            "et": "Keskkonnaohtlik: jäätmed, mis põhjustavad või võivad põhjustada kas vahetult või pikema aja jooksul ohtu ühele või mitmele keskkonnaelemendile",
            "en": "“Ecotoxic:” waste which presents or may present immediate or delayed risks for one or more sectors of the environment"
        }
    },
    {
        "id": "HP15",
        "sort": 1500,
